import dedent from 'dedent';

/**
 * Generates a JsonNodeConverters utility class for format conversions.
 * This class provides static helper methods for converting JsonNode values
 * to format-specific Java types.
 */
export function generateJsonNodeConverters(packageName: string): string {
    return dedent`
        /*
         * Generated by schema-driven-generator - DO NOT EDIT
         * Utility class for JsonNode format conversions
         */

        package ${packageName};

        import com.fasterxml.jackson.databind.JsonNode;
        import java.time.OffsetDateTime;
        import java.time.LocalDate;
        import java.time.LocalTime;
        import java.net.URI;
        import java.util.UUID;

        /**
         * Utility class for converting JsonNode values to format-specific types.
         */
        final class JsonNodeConverters {
            private JsonNodeConverters() {
                // Utility class - do not instantiate
            }

            public static String asString(JsonNode node) {
                if (node == null || node.isNull()) return null;
                return node.asText();
            }

            public static OffsetDateTime toOffsetDateTime(JsonNode node) {
                if (node == null || node.isNull()) return null;
                return OffsetDateTime.parse(node.asText());
            }

            public static LocalDate toLocalDate(JsonNode node) {
                if (node == null || node.isNull()) return null;
                return LocalDate.parse(node.asText());
            }

            public static LocalTime toLocalTime(JsonNode node) {
                if (node == null || node.isNull()) return null;
                return LocalTime.parse(node.asText());
            }

            public static URI toUri(JsonNode node) {
                if (node == null || node.isNull()) return null;
                return URI.create(node.asText());
            }

            public static UUID toUuid(JsonNode node) {
                if (node == null || node.isNull()) return null;
                return UUID.fromString(node.asText());
            }

            public static Integer toInt(JsonNode node) {
                if (node == null || node.isNull()) return null;
                return node.asInt();
            }

            public static Long toLong(JsonNode node) {
                if (node == null || node.isNull()) return null;
                return node.asLong();
            }

            public static Float toFloat(JsonNode node) {
                if (node == null || node.isNull()) return null;
                return (float) node.asDouble();
            }

            public static Double toDouble(JsonNode node) {
                if (node == null || node.isNull()) return null;
                return node.asDouble();
            }
        }
    `;
}
